const ALERT_TYPE_IDOMA: Record<string, string> = {
  attack: 'efu ku iyefu',
  fire: "Ole mi'ola",
  medical: 'O dooche achigili',
  abduction: 'Oka ku o hekpa oche',
  other: "Oha / N'jon",
};

interface I18nCtx {
  lang: Language;
  setLang: (l: Language) => void;
  t: (text: string) => string;
  alertTypeIdoma: (key: string) => string | undefined;
}

const Ctx = createContext<I18nCtx | null>(null);

export function I18nProvider({ children }: { children: ReactNode }) {
  const [lang, setLang] = useState<Language>(() => {
    const saved = localStorage.getItem('cc_lang');
    return saved === 'idoma' ? 'idoma' : 'en';
  });

  useEffect(() => {
    document.documentElement.setAttribute('lang', lang === 'idoma' ? 'idu' : 'en');
  }, [lang]);

  const t = (text: string) => {
    if (lang === 'idoma' && text) return IDOMA[text] ?? text;
    return text;
  };
  const alertTypeIdoma = (key: string) => ALERT_TYPE_IDOMA[key];

  return <Ctx.Provider value={{ lang, setLang, t, alertTypeIdoma }}>{children}</Ctx.Provider>;
}

export function useI18n(): I18nCtx {
  const ctx = useContext(Ctx);
  if (!ctx) throw new Error('useI18n must be used within I18nProvider');
  return ctx;
}

export function LanguageToggle() {
  const { lang, setLang } = useI18n();
  return (
    <button
      onClick={() => setLang(lang === 'en' ? 'idoma' : 'en')}
      className="p-2 rounded-md hover:bg-muted transition-colors text-muted-foreground"
      title={lang === 'en' ? 'Switch to Idoma' : 'Switch to English'}
    >
      {lang === 'en' ? 'ID' : 'EN'}
    </button>
  );
}
